// Ícone de pino customizado (emoji da categoria em cima de um pino verde) — evita depender
// dos ícones padrão do Leaflet, que costumam quebrar em builds com Vite.
function makePinIcon(emoji) {
  return L.divIcon({
    className: "",
    html:
      '<div style="width:30px;height:30px;border-radius:50% 50% 50% 0;background:#76C339;' +
      'transform:rotate(-45deg);display:flex;align-items:center;justify-content:center;' +
      'box-shadow:0 2px 6px rgba(0,0,0,0.4);border:2px solid #042F35;">' +
      '<span style="transform:rotate(45deg);font-size:14px;">' + emoji + "</span></div>",
    iconSize: [30, 30],
    iconAnchor: [15, 30],
    popupAnchor: [0, -28],
  });
}

const userIcon = L.divIcon({
  className: "",
  html: '<div style="width:16px;height:16px;border-radius:50%;background:#4EA5FF;border:3px solid rgba(78,165,255,0.4);"></div>',
  iconSize: [16, 16],
  iconAnchor: [8, 8],
});

// Recentraliza o mapa quando a categoria ou a localização do usuário mudam
function MapAutoFit({ items, coords }) {
  const map = useMap();
  React.useEffect(() => {
    const pts = items.map((p) => [p.lat, p.lng]);
    if (coords) pts.push([coords.lat, coords.lng]);
    if (pts.length === 0) return;
    if (pts.length === 1) {
      map.setView(pts[0], 14);
    } else {
      map.fitBounds(pts, { padding: [30, 30], maxZoom: 15 });
    }
  }, [items, coords, map]);
  return null;
}

function MapView({ items, coords, onSelect }) {
  const center = items.length > 0 ? [items[0].lat, items[0].lng] : [-22.9519, -43.2105];
  return (
    <div style={{ width: "100%", height: 380, borderRadius: 16, overflow: "hidden", border: "1px solid rgba(118,195,57,0.25)" }}>
      <MapContainer center={center} zoom={12} style={{ width: "100%", height: "100%" }} scrollWheelZoom={true}>
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <MapAutoFit items={items} coords={coords} />
        {coords && (
          <Marker position={[coords.lat, coords.lng]} icon={userIcon}>
            <Popup>Você está aqui</Popup>
          </Marker>
        )}
        {items.map((p) => (
          <Marker key={p.id} position={[p.lat, p.lng]} icon={makePinIcon(CAT_ICON[p.cat])} eventHandlers={{ click: () => onSelect(p) }}>
            <Popup>
              <strong>{p.name}</strong>
              <br />
              {p.bairro}
            </Popup>
          </Marker>
        ))}
      </MapContainer>
    </div>
  );
}

